<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>2048 Dark Theme</title>
    <style>
        body {
            background-color: #1a1a1a;
            color: #f9f9f9;
            font-family: 'Clear Sans', 'Helvetica Neue', Arial, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }

        .header {
            text-align: center;
            margin-bottom: 20px;
        }

        h1 {
            font-size: 60px;
            margin: 0;
        }

        #score-container {
            background: #3c3c3c;
            padding: 10px 20px;
            border-radius: 5px;
            font-weight: bold;
            font-size: 24px;
            display: inline-block;
            margin-bottom: 20px;
        }

        #board {
            background-color: #3c3c3c;
            width: 400px;
            height: 400px;
            border-radius: 6px;
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            grid-template-rows: repeat(4, 1fr);
            gap: 12px;
            padding: 12px;
            box-sizing: border-box;
            position: relative;
        }

        .tile {
            width: 85px;
            height: 85px;
            background-color: #4c4c4c;
            border-radius: 3px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 32px;
            font-weight: bold;
            transition: all 0.1s ease-in-out;
        }

        /* Tile Colors */
        .tile-0 { background-color: #4c4c4c; color: transparent; }
        .tile-2 { background-color: #eee4da; color: #776e65; }
        .tile-4 { background-color: #ede0c8; color: #776e65; }
        .tile-8 { background-color: #f2b179; color: white; }
        .tile-16 { background-color: #f59563; color: white; }
        .tile-32 { background-color: #f67c5f; color: white; }
        .tile-64 { background-color: #f65e3b; color: white; }
        .tile-128 { background-color: #edcc61; color: white; font-size: 25px; }
        .tile-256 { background-color: #edcc61; color: white; font-size: 25px; box-shadow: 0 0 10px 2px rgba(237, 204, 97, 0.5); }
        .tile-512 { background-color: #edcc61; color: white; font-size: 25px; box-shadow: 0 0 15px 4px rgba(237, 204, 97, 0.6); }
        .tile-1024 { background-color: #edcc61; color: white; font-size: 20px; }
        .tile-2048 { background-color: #edcc61; color: white; font-size: 20px; box-shadow: 0 0 20px 5px rgba(237, 204, 97, 0.8); }

        #reset {
            margin-top: 20px;
            padding: 10px 25px;
            background-color: #8f7a66;
            color: white;
            border: none;
            border-radius: 3px;
            cursor: pointer;
            font-size: 18px;
            font-weight: bold;
        }

        #reset:hover { background-color: #7f6a56; }
    </style>
</head>
<body>

    <div class="header">
        <h1>2048</h1>
        <div id="score-container">Score: <span id="score">0</span></div>
    </div>

    <div id="board"></div>

    <button id="reset">New Game</button>

    <script>
        (function() {
            let grid = [];
            let score = 0;
            const size = 4;

            const boardEl = document.getElementById('board');
            const scoreEl = document.getElementById('score');
            const resetBtn = document.getElementById('reset');

            function initBoard() {
                boardEl.innerHTML = '';
                for (let i = 0; i < size * size; i++) {
                    const div = document.createElement('div');
                    div.className = 'tile';
                    boardEl.appendChild(div);
                }
            }

            function updateView() {
                const tiles = boardEl.children;
                for (let r = 0; r < size; r++) {
                    for (let c = 0; c < size; c++) {
                        const val = grid[r][c];
                        const tile = tiles[r * size + c];
                        tile.textContent = val === 0 ? '' : val;
                        tile.className = `tile tile-${val}`;
                    }
                }
                scoreEl.textContent = score;
            }

            function spawnTile() {
                const emptyCells = [];
                for (let r = 0; r < size; r++) {
                    for (let c = 0; c < size; c++) {
                        if (grid[r][c] === 0) emptyCells.push({r, c});
                    }
                }
                if (emptyCells.length > 0) {
                    const {r, c} = emptyCells[Math.floor(Math.random() * emptyCells.length)];
                    grid[r][c] = Math.random() < 0.9 ? 2 : 4;
                }
            }

            function slideAndMerge(line) {
                // Slide: remove zeros
                let filtered = line.filter(x => x !== 0);
                let merged = [];
                let currentScoreGain = 0;

                for (let i = 0; i < filtered.length; i++) {
                    if (i < filtered.length - 1 && filtered[i] === filtered[i + 1]) {
                        const combined = filtered[i] * 2;
                        merged.push(combined);
                        currentScoreGain += combined;
                        i++; // skip next since it's merged
                    } else {
                        merged.push(filtered[i]);
                    }
                }

                while (merged.length < size) {
                    merged.push(0);
                }

                return { line: merged, gain: currentScoreGain };
            }

            function move(direction) {
                let moved = false;
                const oldGrid = JSON.stringify(grid);
                let totalGain = 0;

                if (direction === 'left' || direction === 'right') {
                    for (let r = 0; r < size; r++) {
                        let row = grid[r];
                        if (direction === 'right') row.reverse();

                        const result = slideAndMerge(row);
                        totalGain += result.gain;

                        if (direction === 'right') result.line.reverse();
                        grid[r] = result.line;
                    }
                } else if (direction === 'up' || direction === 'down') {
                    for (let c = 0; c < size; c++) {
                        let col = [];
                        for (let r = 0; r < size; r++) col.push(grid[r][c]);
                        if (direction === 'down') col.reverse();

                        const result = slideAndMerge(col);
                        totalGain += result.gain;

                        if (direction === 'down') result.line.reverse();
                        for (let r = 0; r < size; r++) {
                            grid[r][c] = result.line[r];
                        }
                    }
                }

                score += totalGain;
                if (JSON.stringify(grid) !== oldGrid) {
                    moved = true;
                    spawnTile();
                }

                updateView();
                return moved;
            }

            function reset() {
                grid = Array.from({ length: size }, () => Array(size).fill(0));
                score = 0;
                spawnTile();
                spawnTile();
                updateView();
            }

            // Programmatic API for grading
            window.game = {
                size: size,
                reset: reset,
                move: (dir) => move(dir),
                board: () => JSON.parse(JSON.stringify(grid)),
                setBoard: (arr) => {
                    grid = JSON.parse(JSON.stringify(arr));
                    updateView();
                },
                score: () => score,
            };

            // Event Listeners
            window.addEventListener('keydown', (e) => {
                switch(e.key) {
                    case 'ArrowLeft':  move('left'); break;
                    case 'ArrowRight': move('right'); break;
                    case 'ArrowUp':    move('up'); break;
                    case 'ArrowDown':  move('down'); break;
                }
            });

            resetBtn.addEventListener('click', reset);

            // Startup
            initBoard();
            reset();
        })();
    </script>
</body>
</html>
